var n=`0027-uzvar`;var t=`world-0027`;var a=`UA`;var r=`eastern-europe`;var s=8;var o=73;var m={en:`Uzvar`,ua:`Узвар`};var d={en:`A classic dish from Ukraine, featuring uzvar dried fruit mix, lemon, honey. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Україна. Основні складники: суміш сухофруктів для узвару, лимон, мед. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 25 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 25 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:25,i:[[`uzvar-dried-fruit-mix`,250,`g`],[`water`,1800,`ml`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`honey`,80,`g`],[`lemon`,1,`pcs`]]},{en:`Chill briefly if appropriate, garnish with the listed ingredients and serve at the intended temperature.`,ua:`За потреби недовго охолодіть, прикрасьте зазначеними складниками й подавайте за потрібної температури.`,t:[`garnishing`],m:45,i:[]}];var g={slug:n,id:t,country:`UA`,region:r,servings:8,minutes:73,title:m,text:d,steps:u};export{a as country,g as default,t as id,o as minutes,r as region,s as servings,n as slug,u as steps,d as text,m as title};